                + "UHgqXmuvk2X/Ww==";

        try {
            final KeyFactory fac = KeyFactory.getInstance("RSA");
            final PKCS8EncodedKeySpec privKeySpec = new PKCS8EncodedKeySpec(Base64.decodeBase64(str));
