@SuppressWarnings("PMD.SystemPrintln")
    public static void main(String... args) throws InterruptedException, ExecutionException, IOException {
        // Replace these with your client id and secret
        final String clientId = "your client id";
        final String clientSecret = "your client secret";
        final String secretState = "secret" + new Random().nextInt(999_999);
        final HttpClientConfig clientConfig = new AhcHttpClientConfig(new DefaultAsyncHttpClientConfig.Builder()
                .setMaxConnections(5)
                .setRequestTimeout(10_000)
                .setPooledConnectionIdleTimeout(1_000)
                .setReadTimeout(1_000)
                .build());

        try (OAuth20Service service = new ServiceBuilder(clientId)
                .apiSecret(clientSecret)
                .defaultScope("profile") // replace with desired scope
                .callback("http://example.com/callback")
                .httpClientConfig(clientConfig)
                .build(GoogleApi20.instance())) {
            final Scanner in = new Scanner(System.in, "UTF-8");

            System.out.println("=== " + NETWORK_NAME + "'s OAuth Workflow ===");
            System.out.println();

            // Obtain the Authorization URL
            System.out.println("Fetching the Authorization URL...");
            //pass access_type=offline to get refresh token
            //https://developers.google.com/identity/protocols/OAuth2WebServer#preparing-to-start-the-oauth-20-flow
            final Map<String, String> additionalParams = new HashMap<>();
            additionalParams.put("access_type", "offline");
            //force to reget refresh token (if user are asked not the first time)
            additionalParams.put("prompt", "consent");
            final String authorizationUrl = service.createAuthorizationUrlBuilder()
                    .state(secretState)
                    .additionalParams(additionalParams)
                    .build();
            System.out.println("Got the Authorization URL!");
            System.out.println("Now go and authorize ScribeJava here:");
            System.out.println(authorizationUrl);
            System.out.println("And paste the authorization code here");
            System.out.print(">>");
            final String code = in.nextLine();
            System.out.println();

            System.out.println("And paste the state from server here. We have set 'secretState'='"
                    + secretState + "'.");
            System.out.print(">>");
            final String value = in.nextLine();
            if (secretState.equals(value)) {
                System.out.println("State value does match!");
            } else {
                System.out.println("Ooops, state value does not match!");
                System.out.println("Expected = " + secretState);
                System.out.println("Got      = " + value);
                System.out.println();
            }

            System.out.println("Trading the Authorization Code for an Access Token...");
            OAuth2AccessToken accessToken = service.getAccessToken(code);
            System.out.println("Got the Access Token!");
            System.out.println("(The raw response looks like this: " + accessToken.getRawResponse()
                    + "')");

            System.out.println("Refreshing the Access Token...");
            accessToken = service.refreshAccessToken(accessToken.getRefreshToken());
            System.out.println("Refreshed the Access Token!");
            System.out.println("(The raw response looks like this: " + accessToken.getRawResponse()
                    + "')");
            System.out.println();

            // Now let's go and ask for a protected resource!
            System.out.println("Now we're going to access a protected resource...");
            while (true) {
                System.out.println("Paste fieldnames to fetch (leave empty to get profile, 'exit' to stop example)");
                System.out.print(">>");
                final String query = in.nextLine();
                System.out.println();

                final String requestUrl;
                if ("exit".equals(query)) {
                    break;
                } else if (query == null || query.isEmpty()) {
                    requestUrl = PROTECTED_RESOURCE_URL;
                } else {
                    requestUrl = PROTECTED_RESOURCE_URL + "?fields=" + query;
                }

                final OAuthRequest request = new OAuthRequest(Verb.GET, requestUrl);
                service.signRequest(accessToken, request);
                System.out.println();
                try (Response response = service.execute(request)) {
                    System.out.println(response.getCode());
                    System.out.println(response.getBody());
                }
                System.out.println();
            }
        }
    }

@SuppressWarnings({"unchecked", "rawtypes", "PMD.SystemPrintln"})
    public static void main(String... args) throws InterruptedException, ExecutionException,
            UnsupportedEncodingException, IOException, NoSuchAlgorithmException, KeyManagementException {
        // Replace these with your client id and secret
        final String clientId = "your client id";
        final String clientSecret = "your client secret";

        final NingHttpClientConfig clientConfig = new NingHttpClientConfig(new AsyncHttpClientConfig.Builder()
                .setMaxConnections(5)
                .setRequestTimeout(10_000)
                .setAllowPoolingConnections(false)
                .setPooledConnectionIdleTimeout(1_000)
                .setReadTimeout(10_000)
                .build());

        //IT's important! Salesforce upper require TLS v1.1 or higher
        SalesforceApi.initTLSv11orUpper();
        try (OAuth20Service service = new ServiceBuilder(clientId)
                .apiSecret(clientSecret)
                .httpClientConfig(clientConfig)
                .callback("https://www.example.com/callback")
                .build(SalesforceApi.instance())) {
            System.out.println("=== " + NETWORK_NAME + "'s OAuth20 Workflow ===");
            System.out.println();
            // Obtain the Authorization URL
            System.out.println("Fetching the Authorization URL...");
            final String authorizationUrl = service.getAuthorizationUrl();
            System.out.println("Got the Authorization URL!");
            System.out.println("Now go and authorize ScribeJava here:");
            System.out.println(authorizationUrl);
            System.out.println("And paste the authorization code here");
            System.out.print(">>");
            final String code;
            try (Scanner in = new Scanner(System.in)) {
                code = in.nextLine();
            }
            System.out.println();
            final String codeEncoded = URLDecoder.decode(code, "UTF-8");
            // Trade the Request Token and Verifier for the Access Token
            System.out.println("Trading the Request Token for an Access Token...");

            final OAuth2AccessToken accessToken = service.getAccessToken(codeEncoded);
            final SalesforceToken salesforceAccessToken;
            if (accessToken instanceof SalesforceToken) {
                salesforceAccessToken = (SalesforceToken) accessToken;
            } else {
                throw new IllegalStateException("Salesforce API didn't return SalesforceToken.");
            }
            System.out.println("Got the Access Token!");

            System.out.println("(The raw response looks like this: " + accessToken.getRawResponse()
                    + "')");
            System.out.println();
            System.out.println("Instance is: " + salesforceAccessToken.getInstanceUrl());
            // Now let's go and ask for a protected resource!
            System.out.println("Now we're reading accounts from the Salesforce org (maxing them to 10).");
            // Sample SOQL statement
            final String queryEncoded = URLEncoder.encode("Select Id, Name from Account LIMIT 10", "UTF-8");
            // Building the query URI. We've parsed the instance URL from the
            // accessToken request.
            final String url = salesforceAccessToken.getInstanceUrl() + "/services/data/v36.0/query?q=" + queryEncoded;
            System.out.println();
            System.out.println("Full URL: " + url);
            final OAuthRequest request = new OAuthRequest(Verb.GET, url);
            System.out.println();
            try (Response response = service.execute(request)) {
                System.out.println(response.getCode());
                System.out.println(response.getBody());
            }
        }
    }

@Test
    public void shouldThrowExceptionIfResponseIsError() throws IOException {
        final String body = "{\"error\":"
                + "{\"message\":\"This authorization code has been used.\","
                + "\"type\":\"OAuthException\","
                + "\"code\":100,"
                + "\"fbtrace_id\":\"DtxvtGRaxbB\"}}";
        try (Response response = error(body)) {

            final FacebookAccessTokenErrorResponse fateR = assertThrows(FacebookAccessTokenErrorResponse.class,
                    new ThrowingRunnable() {
                @Override
                public void run() throws Throwable {
                    extractor.extract(response);
                }
            });

            assertEquals("This authorization code has been used.", fateR.getErrorMessage());
            assertEquals("OAuthException", fateR.getType());
            assertEquals(100, fateR.getCodeInt());
            assertEquals("DtxvtGRaxbB", fateR.getFbtraceId());
            assertEquals(body, fateR.getResponse().getBody());
        }
    }

@Override
                public void run() throws Throwable {
                    extractor.extract(response);
                }

private static Response error(String body) {
        return new Response(400, /* message */ null, /* headers */ Collections.<String, String>emptyMap(), body);
    }

@Test
    public void testSigGeneration() {
        final OAuth2AccessToken accessToken = new OAuth2AccessToken("d3iwa.403gvrs194740652m1k4w2a503k3c");
        final OAuthRequest request = new OAuthRequest(Verb.GET, URL);
        service.signRequest(accessToken, request);
        assertEquals("96127f5ca29a8351399e94bbd284ab16", findParam(request.getQueryStringParams(), "sig"));
    }

private static String findParam(ParameterList list, String key) {
        for (Parameter param : list.getParams()) {
            if (param.getKey().equals(key)) {
                return param.getValue();
            }
        }
        return null;
    }

@Test
    public void testErrorExtraction() throws IOException {

        final FitBitJsonTokenExtractor extractor = new FitBitJsonTokenExtractor();
        final OAuth2AccessTokenErrorResponse thrown = assertThrows(OAuth2AccessTokenErrorResponse.class,
                new ThrowingRunnable() {
            @Override
            public void run() throws Throwable {
                extractor.generateError(new Response(403, null, null, ERROR_JSON));
            }
        });
        assertSame(OAuth2Error.INVALID_GRANT, thrown.getError());
        assertEquals(ERROR_DESCRIPTION, thrown.getErrorDescription());
    }

@Override
            public void run() throws Throwable {
                extractor.generateError(new Response(403, null, null, ERROR_JSON));
            }
